//! Data-driven grammar registry generated by `build.rs` from `third_party/ECOSYSTEM.toml`.
//! Grammars without a dedicated extractor ([`SupportedLanguage`]) get symbols and references
//! from their upstream `tags.scm` (tree-sitter tagging convention: `@name`,
//! `@definition.*`, `@reference.*`).

use crate::symbols::{AstCall, AstFileSummary, AstSymbol, Span, SymbolKind};
use std::path::Path;
use streaming_iterator::StreamingIterator;
use tree_sitter::{Language, Parser, Query, QueryCursor};

pub struct Grammar {
    pub name: &'static str,
    /// Extensions or full file names from the grammar's `tree-sitter.json`.
    pub file_types: &'static [&'static str],
    raw: unsafe extern "C" fn() -> *const (),
    pub tags: Option<&'static str>,
}

include!(concat!(env!("OUT_DIR"), "/grammars.rs"));

impl Grammar {
    pub fn language(&self) -> Language {
        // SAFETY: `raw` is the renamed `tree_sitter_<name>` entry point compiled by build.rs.
        Language::new(unsafe { tree_sitter_language::LanguageFn::from_raw(self.raw) })
    }

    pub fn by_name(name: &str) -> Option<&'static Grammar> {
        GRAMMARS.iter().find(|g| g.name == name)
    }

    pub fn for_path(path: &Path) -> Option<&'static Grammar> {
        let file = path.file_name()?.to_str()?;
        let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
        GRAMMARS.iter().find(|g| {
            g.file_types.iter().any(|t| *t == file || t.eq_ignore_ascii_case(ext))
                || (g.file_types.is_empty() && g.name.eq_ignore_ascii_case(ext))
        })
    }

    /// Parse and extract definitions/references through `tags.scm` (structure-only when absent).
    pub fn extract(&self, path: &str, content: &str) -> Result<AstFileSummary, String> {
        let lang = self.language();
        let mut parser = Parser::new();
        parser.set_language(&lang).map_err(|e| format!("{}: {e}", self.name))?;
        let tree = parser.parse(content, None).ok_or("parse cancelled")?;
        let root = tree.root_node();
        let mut summary = AstFileSummary {
            path: path.to_string(),
            language: self.name.to_string(),
            symbols: Vec::new(),
            calls: Vec::new(),
            imports: Vec::new(),
            parse_errors: usize::from(root.has_error()),
            line_count: content.lines().count(),
            byte_count: content.len(),
        };
        let Some(tags) = self.tags else { return Ok(summary) };
        let query = Query::new(&lang, tags).map_err(|e| format!("{} tags.scm: {e}", self.name))?;
        let names = query.capture_names();
        let mut cursor = QueryCursor::new();
        let mut it = cursor.matches(&query, root, content.as_bytes());
        while let Some(m) = it.next() {
            let mut name = None;
            let mut role = None;
            for c in m.captures() {
                let cap = names[c.index as usize];
                if cap == "name" {
                    name = c.node.utf8_text(content.as_bytes()).ok().map(|s| (s.to_string(), c.node));
                } else if cap.starts_with("definition.") || cap.starts_with("reference.") {
                    role = Some((cap, c.node));
                }
            }
            let (Some((text, name_node)), Some((cap, node))) = (name, role) else { continue };
            if let Some(kind) = cap.strip_prefix("definition.") {
                summary.symbols.push(AstSymbol {
                    name: text,
                    kind: kind_of(kind),
                    span: Span::from_node(&node),
                    signature: None,
                    doc: None,
                    parent_scope: None,
                });
            } else {
                summary.calls.push(AstCall { callee: text, caller_scope: None, span: Span::from_node(&name_node) });
            }
        }
        Ok(summary)
    }
}

fn kind_of(tag: &str) -> SymbolKind {
    match tag {
        "function" => SymbolKind::Function,
        "method" => SymbolKind::Method,
        "class" => SymbolKind::Class,
        "interface" => SymbolKind::Interface,
        "module" | "namespace" => SymbolKind::Module,
        "constant" => SymbolKind::Constant,
        "type" => SymbolKind::TypeAlias,
        "enum" => SymbolKind::Enum,
        "struct" => SymbolKind::Struct,
        "trait" => SymbolKind::Trait,
        "macro" => SymbolKind::Function,
        _ => SymbolKind::Variable,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_registered_grammar_loads_and_parses() {
        for g in GRAMMARS {
            let lang = g.language();
            assert!(lang.abi_version() >= tree_sitter::MIN_COMPATIBLE_LANGUAGE_VERSION, "{}", g.name);
            g.extract("x", "").unwrap_or_else(|e| panic!("{}: {e}", g.name));
        }
    }
}
